{"implementation":"import math
def solve(case):
    if 'matrix' not in case:
        raise ValueError('case missing matrix')
    matrix = case['matrix']
    if not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError('matrix must be non-empty list of rows')
    rows = len(matrix)
    cols = len(matrix[0])
    for row in matrix:
        if not isinstance(row, list) or len(row) != cols:
            raise ValueError('all rows must be lists of equal length')
    idf = []
    for j in range(cols):
        df = sum(1 for i in range(rows) if matrix[i][j] != 0)
        idf.append(math.log(1 + rows / (1 + df)))
    weighted_matrix = []
    row_degree = []
    for i in range(rows):
        weighted_row = [matrix[i][j] * idf[j] for j in range(cols)]
        weighted_matrix.append(weighted_row)
        row_degree.append(sum(weighted_row))
    return {'idf': idf, 'row_degree': row_degree, 'weighted_matrix': weighted_matrix}"}
